rules.rule10secondCSV_ZSTD:
{
  "id": "rule10secondCSV_ZSTD",
  "name": "10s周期文件压缩",
  "sql": "SELECT * FROM spi_1000ms_stream",
  "actions": [
    {
      "file": {
        "path": "/bigdata/periodic.zstd",
        "format": "delimited",
        "fileType": "csv",
        "hasHeader": true,
        "sendSingle": true,
        "rollingInterval": "10s",
        "compression": "zstd",
        "rollingNamePattern": "suffix",
        "rollingHook": "nano",
        "rollingHookProps": {
          "server": "tcp://127.0.0.1:1883",
          "topic": "file_transfer",
          "ruleType": "periodic",
          "delete": 10
        }
      }
    }
  ],
  "options": {
    "sendError": false,
    "sendNilField": true
  }
}

rules.ruleCellt:
{
  "id": "ruleCellt",
  "name": "电池电压收集",
  "sql": "SELECT event_time() as et, props(\"v\") as v, props(\"sv\") as sv, props(\"cs\") as cs, props(\"nc\") as nc, collectt(HvBattCellTInfoHvBattTSnsrNr, HvBattCellTInfoHvBattSnsrT) as data FROM celltStream WHERE IsNull(data) = false",
  "actions": [
    {
      "mqtt": {
        "server": "tcp://127.0.0.1:1883",
        "topic": "result/cell/2/ruleCellt/{{.cs}}/{{.nc}}/{{.v}}/{{.sv}}/{{.et}}",
        "format": "delimited",
        "fields": ["data"],
        "hasHeader": false,
        "sendSingle": true,
        "compression": "zstd",
        "encryption": "aes",
        "encProps": {
          "mode": "gcm",
          "iv": "mao+aO2Bc6Du0GaE",
          "aad": "TSPDzsM0tJvbNwxDf+x43g==",
          "tagSize": 32
        }
      }
    }
  ]
}

